// Monochrome category artwork shared by the mobile menu and homepage.
function CategoryIcon({category,size=28}){
 const props={size,strokeWidth:1.8,absoluteStrokeWidth:true,'aria-hidden':true};
 switch(category){
  case 'Bedrooms': return <BedDouble {...props}/>;
  case 'Living Rooms': return <Sofa {...props}/>;
  case 'Dining Room': return <svg width={size} height={size} viewBox="0 0 32 32" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="M7 13h18M10 13l-2 13m14-13 2 13M5 19H2v-7h5v14H5zm22 0h3v-7h-5v14h2z"/><path d="M10 10h12l2 3H8z"/></svg>;
  case 'Appliances': return <WashingMachine {...props}/>;
  case 'Electronics': return <span className="ez-category-duo"><Tv {...props} size={size}/><Monitor size={Math.round(size*.52)} strokeWidth={1.8} aria-hidden="true"/></span>;
  case 'Pre-Rented Products': return <Tags {...props}/>;
  case 'Deals': return <BadgePercent {...props}/>;
  default: return null;
 }
}

