const mapProduct = p => ({id:p.id,title:p.title_en,titleEs:p.title_es||p.title_en,description:p.description_en||'',descriptionEs:p.description_es||p.description_en||'',category:p.category,price:Number(p.price),weekly:p.weekly_price,image:p.image_url});
const money = n => '$'+Number(n||0).toFixed(2);

function App(){
 const [lang,setLang]=useState(()=>localStorage.getItem('ez_lang')==='es'?'es':'en');
 const [page,setPage]=useState('Home');
 const [products,setProducts]=useState([]),[loading,setLoading]=useState(true),[productError,setProductError]=useState('');
 const [content,setContent]=useState(()=>{try{return JSON.parse(localStorage.getItem('ez_content')||'{}')}catch{return {}}});
 const [user,setUser]=useState(null),[admin,setAdmin]=useState(false),[staffRole,setStaffRole]=useState(null),[authLoading,setAuthLoading]=useState(true);
 const [showPassword,setShowPassword]=useState(false);
 const [authMode,setAuthMode]=useState('signin'),[login,setLogin]=useState(false),[loginBusy,setLoginBusy]=useState(false),[loginError,setLoginError]=useState(''),[loginSuccess,setLoginSuccess]=useState('');
 const [accountMenu,setAccountMenu]=useState(false),[orders,setOrders]=useState([]),[payments,setPayments]=useState([]),[accountLoading,setAccountLoading]=useState(false),[accountError,setAccountError]=useState('');
 const [tickets,setTickets]=useState([]),[selectedTicket,setSelectedTicket]=useState(null),[ticketMessages,setTicketMessages]=useState([]),[ticketBusy,setTicketBusy]=useState(false),[ticketLoading,setTicketLoading]=useState(false),[ticketError,setTicketError]=useState(''),[ticketNotice,setTicketNotice]=useState(''),[ticketFilter,setTicketFilter]=useState('all');
 const [modal,setModal]=useState(false),[saving,setSaving]=useState(false),[formError,setFormError]=useState('');
 const [cart,setCart]=useState([]),[cartOpen,setCartOpen]=useState(false),[mobile,setMobile]=useState(false),[search,setSearch]=useState(''),[notice,setNotice]=useState('');
 const canEditProducts=['owner','manager','inventory'].includes(staffRole);
 const t=s=>lang==='es'?(translations[s]||s):s;
 useEffect(()=>{document.documentElement.lang=lang;localStorage.setItem('ez_lang',lang)},[lang]);
 useEffect(()=>{localStorage.setItem('ez_content',JSON.stringify(content))},[content]);
 async function loadProducts(){setLoading(true);setProductError('');try{const {data,error}=await supabase.from('products').select('*').order('created_at',{ascending:false});if(error)throw error;setProducts((data||[]).map(mapProduct))}catch(e){setProductError(e.message||'Unable to load products')}finally{setLoading(false)}}
 useEffect(()=>{loadProducts()},[]);
 useEffect(()=>{
  let active=true,sequence=0;
  async function updateSession(session){const current=++sequence;if(!active)return;setUser(session?.user||null);if(!session?.user){setAdmin(false);setStaffRole(null);setAuthLoading(false);return}try{const {data,error}=await supabase.from('staff_members').select('role,is_active').eq('user_id',session.user.id).maybeSingle();if(active&&current===sequence){const role=!error&&data?.is_active?data.role:null;setStaffRole(role);setAdmin(!!role)}}catch{if(active&&current===sequence){setAdmin(false);setStaffRole(null)}}finally{if(active&&current===sequence)setAuthLoading(false)}}
  supabase.auth.getSession().then(({data})=>updateSession(data.session)).catch(()=>{if(active){setUser(null);setAdmin(false);setStaffRole(null);setAuthLoading(false)}});
  const {data:listener}=supabase.auth.onAuthStateChange((_event,session)=>{setTimeout(()=>{if(active)updateSession(session)},0)});
  return()=>{active=false;listener.subscription.unsubscribe()};
 },[]);
 useEffect(()=>{
  if(!user||!['My Orders','Payment History'].includes(page))return;
  let active=true;
  (async()=>{setAccountLoading(true);setAccountError('');try{
   if(page==='My Orders'){const {data,error}=await supabase.from('customer_orders').select('id,order_number,status,total_amount,created_at').eq('user_id',user.id).order('created_at',{ascending:false});if(error)throw error;if(active)setOrders(data||[])}
   else{const {data,error}=await supabase.from('customer_payments').select('id,order_id,amount,status,paid_at,created_at').eq('user_id',user.id).order('created_at',{ascending:false});if(error)throw error;if(active)setPayments(data||[])}
  }catch(e){if(active)setAccountError(e.message||'Unable to load account records')}finally{if(active)setAccountLoading(false)}})();
  return()=>{active=false};
 },[user?.id,page]);
 async function loadTickets(){
  if(!user)return;
  setTicketLoading(true);setTicketError('');
  const {data,error}=await supabase.from('support_tickets').select('id,customer_id,subject,description,status,priority,assigned_to,resolved_at,created_at,updated_at').order('updated_at',{ascending:false});
  if(error)setTicketError(error.message);else setTickets(data||[]);
  setTicketLoading(false);
 }
 useEffect(()=>{if(user&&['My Support Tickets','Admin Dashboard'].includes(page))loadTickets()},[user?.id,page,admin]);
 useEffect(()=>{
  if(!user||!selectedTicket){setTicketMessages([]);return;}
  let active=true;
  supabase.from('support_ticket_messages').select('id,ticket_id,sender_id,message,created_at').eq('ticket_id',selectedTicket.id).order('created_at',{ascending:true}).then(({data,error})=>{if(active){if(error)setTicketError(error.message);else setTicketMessages(data||[])}});
  return()=>{active=false};
 },[selectedTicket?.id,user?.id]);
 async function createTicket(e){
  e.preventDefault();if(!user||ticketBusy)return;
  setTicketBusy(true);setTicketError('');setTicketNotice('');
  const form=e.currentTarget;const f=new FormData(form);
  const subject=String(f.get('subject')||'').trim(),description=String(f.get('description')||'').trim();
  if(subject.length<3||description.length<1){setTicketError('Enter a subject and description.');setTicketBusy(false);return}
  const {data,error}=await supabase.from('support_tickets').insert({customer_id:user.id,subject,description}).select('id,customer_id,subject,description,status,created_at,updated_at').single();
  if(error)setTicketError(error.message);else{form.reset();setTicketNotice(t('Ticket submitted successfully.'));await loadTickets();setSelectedTicket(data);setPage('My Support Tickets')}
  setTicketBusy(false);
 }
 async function replyTicket(e){
  e.preventDefault();if(!user||!selectedTicket||ticketBusy)return;
  const form=e.currentTarget;const f=new FormData(form),message=String(f.get('message')||'').trim();if(!message)return;
  setTicketBusy(true);setTicketError('');
  const {error}=await supabase.from('support_ticket_messages').insert({ticket_id:selectedTicket.id,sender_id:user.id,message});
  if(error)setTicketError(error.message);else{
   form.reset();
   const result=await supabase.from('support_ticket_messages').select('id,ticket_id,sender_id,message,created_at').eq('ticket_id',selectedTicket.id).order('created_at',{ascending:true});
   if(result.error)setTicketError(result.error.message);else setTicketMessages(result.data||[]);
  }
  setTicketBusy(false);
 }
 async function changeTicketStatus(status){
  if(!admin||!selectedTicket||ticketBusy)return;
  setTicketBusy(true);setTicketError('');
  const {error}=await supabase.from('support_tickets').update({status}).eq('id',selectedTicket.id);
  if(error)setTicketError(error.message);else{setSelectedTicket(v=>({...v,status}));setTickets(v=>v.map(x=>x.id===selectedTicket.id?{...x,status}:x));setTicketNotice(t('Ticket updated.'))}
  setTicketBusy(false);
 }
 async function updateTicketField(patch){
  if(!admin||!selectedTicket||ticketBusy)return;
  setTicketBusy(true);setTicketError('');
  const {error}=await supabase.from('support_tickets').update(patch).eq('id',selectedTicket.id);
  if(error)setTicketError(error.message);else{setSelectedTicket(v=>({...v,...patch}));setTickets(v=>v.map(x=>x.id===selectedTicket.id?{...x,...patch}:x));setTicketNotice('Ticket updated.');}
  setTicketBusy(false);
 }
 const ticketStatusLabel=status=>t(status==='open'?'Open':status==='in_progress'?'In Progress':'Resolved');
 const ticketPanel=<div className="ez-ticket-layout">
  <div className="ez-ticket-list">
   <div className="ez-ticket-list-top"><h2><Ticket size={21}/> {t('Support Tickets')}</h2><button type="button" onClick={loadTickets} disabled={ticketLoading}>{t('Retry')}</button></div>
   {admin&&<div className="ez-ticket-filters"><select value={ticketFilter} onChange={e=>setTicketFilter(e.target.value)} aria-label="Filter tickets"><option value="all">All tickets</option><option value="open">{t('Open')}</option><option value="in_progress">{t('In Progress')}</option><option value="resolved">{t('Resolved')}</option></select><span>{tickets.filter(x=>ticketFilter==='all'||x.status===ticketFilter).length} tickets</span></div>}
   {ticketLoading?<p className="muted">Loading tickets...</p>:!tickets.filter(x=>!admin||ticketFilter==='all'||x.status===ticketFilter).length?<p className="muted">{t('No tickets yet.')}</p>:tickets.filter(x=>!admin||ticketFilter==='all'||x.status===ticketFilter).map(ticket=><button key={ticket.id} type="button" className={'ez-ticket-item '+(selectedTicket?.id===ticket.id?'active':'')} onClick={()=>{setTicketError('');setTicketNotice('');setSelectedTicket(ticket)}}><span className="ez-ticket-item-title">{ticket.subject}</span><span className={'ez-ticket-status '+ticket.status}>{ticketStatusLabel(ticket.status)}</span><small>#{ticket.id.slice(0,8).toUpperCase()} · {new Date(ticket.created_at).toLocaleDateString()}</small>{admin&&<small>Customer: {ticket.customer_id.slice(0,8)}... · {ticket.priority||'normal'} priority</small>}</button>)}
  </div>
  <div className="ez-ticket-detail">{selectedTicket?<>
   <div className="ez-ticket-detail-head"><div><small>#{selectedTicket.id.slice(0,8).toUpperCase()}</small><h2>{selectedTicket.subject}</h2><span className={'ez-ticket-status '+selectedTicket.status}>{ticketStatusLabel(selectedTicket.status)}</span></div>{admin&&<label>Priority<select value={selectedTicket.priority||'normal'} disabled={ticketBusy} onChange={e=>updateTicketField({priority:e.target.value})}>{['low','normal','high','urgent'].map(x=><option key={x} value={x}>{x}</option>)}</select></label>}{admin&&<label>Change status<select value={selectedTicket.status} disabled={ticketBusy} onChange={e=>changeTicketStatus(e.target.value)}><option value="open">{t('Open')}</option><option value="in_progress">{t('In Progress')}</option><option value="resolved">{t('Resolved')}</option></select></label>}</div>
   <div className="ez-ticket-conversation"><div className="ez-ticket-bubble"><small>Original request · {new Date(selectedTicket.created_at).toLocaleString()}</small><p>{selectedTicket.description}</p></div>{ticketMessages.map(m=><div className={'ez-ticket-bubble '+(m.sender_id===user.id?'mine':'')} key={m.id}><small>{m.sender_id===user.id?'You':admin?'Customer':'Support team'} · {new Date(m.created_at).toLocaleString()}</small><p>{m.message}</p></div>)}</div>
   <form className="ez-ticket-reply" onSubmit={replyTicket}><label>{t('Reply')}<textarea name="message" rows="3" maxLength="10000" required placeholder={t('Message')}/></label><button className="primary" disabled={ticketBusy} type="submit"><Send size={16}/>{t('Reply')}</button></form>
  </>:<div className="ez-ticket-placeholder"><MessageSquare size={40}/><p>{t('Select a ticket to view the conversation.')}</p></div>}</div>
 </div>;
 function showAuth(mode='signin'){setShowPassword(false);setAuthMode(mode);setLoginError('');setLoginSuccess('');setAccountMenu(false);setLogin(true)}
 async function submitAuth(e){e.preventDefault();if(loginBusy)return;setLoginBusy(true);setLoginError('');setLoginSuccess('');const f=new FormData(e.currentTarget);const email=String(f.get('email')||'').trim(),password=String(f.get('password')||'');try{
  if(authMode==='signup'){
   if(password.length<6)throw new Error('Password must contain at least 6 characters.');
   const {error}=await supabase.auth.signUp({email,password,options:{emailRedirectTo:window.location.origin}});if(error)throw error;
   setAuthMode('signin');setLoginSuccess(t('Check your email for a verification link.'));
  }else if(authMode==='reset'){
   const {error}=await supabase.auth.resetPasswordForEmail(email,{redirectTo:window.location.origin});if(error)throw error;
   setLoginSuccess(t('If an account exists, check your email for a reset link.'));
  }else if(authMode==='newpassword'){
   const {error}=await supabase.auth.updateUser({password});if(error)throw error;
   setLoginSuccess(t('Password updated. Please sign in.'));setAuthMode('signin');
  }else{
   const {data,error}=await supabase.auth.signInWithPassword({email,password});if(error)throw error;
   if(!data.user?.email_confirmed_at){await supabase.auth.signOut();throw new Error(t('Verify your email before signing in.'))}
   setLogin(false);setPage('My Account');setAccountMenu(false);
  }
 }catch(err){setLoginError(err.message||'Authentication failed')}finally{setLoginBusy(false)}}
 useEffect(()=>{
  const hash=window.location.hash;
  if(hash.includes('type=recovery')){showAuth('newpassword')}
  const {data:listener}=supabase.auth.onAuthStateChange(event=>{if(event==='PASSWORD_RECOVERY')setTimeout(()=>showAuth('newpassword'),0)});
  return()=>listener.subscription.unsubscribe();
 },[]);
 async function signOut(){const {error}=await supabase.auth.signOut();if(error){window.alert(error.message);return}setUser(null);setAdmin(false);setStaffRole(null);setAccountMenu(false);setModal(false);setOrders([]);setPayments([]);setTickets([]);setSelectedTicket(null);setTicketMessages([]);setPage('Home')}
 async function addProduct(e){e.preventDefault();if(!canEditProducts||saving)return;setSaving(true);setFormError('');const f=new FormData(e.currentTarget),file=f.get('image');let uploadedPath=null;try{
  if(!(file instanceof File)||!file.size||!file.type.startsWith('image/'))throw new Error('Select a product image.');if(file.size>10*1024*1024)throw new Error('Image must be under 10 MB.');
  const ext=(file.name.split('.').pop()||'jpg').toLowerCase().replace(/[^a-z0-9]/g,'');uploadedPath=`${crypto.randomUUID()}.${ext}`;
  const {error:uploadError}=await supabase.storage.from('product-images').upload(uploadedPath,file,{contentType:file.type,upsert:false});if(uploadError)throw uploadError;
  const {data:imageData}=supabase.storage.from('product-images').getPublicUrl(uploadedPath);
  const record={title_en:String(f.get('title')||'').trim(),title_es:String(f.get('titleEs')||'').trim(),description_en:String(f.get('description')||'').trim(),description_es:String(f.get('descriptionEs')||'').trim(),category:cats.includes(page)?page:String(f.get('category')||cats[0]),price:Number(f.get('price')),weekly_price:f.get('weekly')===''?null:Number(f.get('weekly')),image_url:imageData.publicUrl};
  const {error:insertError}=await supabase.from('products').insert(record);if(insertError)throw insertError;uploadedPath=null;await loadProducts();setModal(false);setNotice(t('Product saved successfully.'));
 }catch(err){setFormError(err.message||'Unable to save product.');if(uploadedPath)await supabase.storage.from('product-images').remove([uploadedPath])}finally{setSaving(false)}}
 async function removeProduct(id){if(!['owner','manager'].includes(staffRole)||!window.confirm(t('Are you sure you want to delete this product?')))return;const {error}=await supabase.from('products').delete().eq('id',id);if(error){window.alert(error.message);return}setProducts(v=>v.filter(p=>p.id!==id));setCart(v=>v.filter(p=>p.id!==id));setNotice(t('Product deleted successfully.'))}
 function addInfo(e){e.preventDefault();if(!admin)return;const f=new FormData(e.currentTarget);setContent(v=>({...v,[page]:[...(v[page]||[]),{id:Date.now(),title:f.get('title'),titleEs:f.get('titleEs')||f.get('title'),description:f.get('description'),descriptionEs:f.get('descriptionEs')||f.get('description')}]}));setModal(false)}
 const go=p=>{setPage(p);setMobile(false);setSearch('');setNotice('');setAccountMenu(false);window.scrollTo(0,0)};
 const runSearch=()=>{setPage('Search Results');setMobile(false);window.scrollTo(0,0)};
 const filtered=products.filter(p=>(page==='Home'||page==='Search Results'||p.category===page)&&(`${p.title||''} ${p.description||''} ${p.titleEs||''} ${p.descriptionEs||''} ${p.category||''} ${translations[p.category]||''}`.toLowerCase().includes(search.toLowerCase())));
 const isInfo=info.includes(page),isAccount=['My Account','My Orders','Payment History','Admin Dashboard','My Support Tickets'].includes(page);
 const grid=emptySearch=>loading?<div className="emptyproducts">{t('Loading products...')}</div>:productError?<div className="emptyproducts"><p>{t('Unable to load products. Please try again.')}</p><button onClick={loadProducts}>{t('Retry')}</button></div>:<ProductGrid items={filtered} lang={lang} t={t} admin={['owner','manager'].includes(staffRole)} remove={removeProduct} add={p=>setCart(v=>[...v,p])} emptySearch={emptySearch}/>;
 const openModal=()=>{setFormError('');setModal(true)};
 return <>
 <style>{'\n/* Modern split-screen account experience */\n.ez-auth-overlay{position:fixed;inset:0;z-index:9999;background:rgba(9,19,39,.75);backdrop-filter:blur(8px);display:flex;align-items:center;justify-content:center;padding:22px;overflow-y:auto}\n.ez-auth-shell{width:min(940px,100%);min-height:565px;display:grid;grid-template-columns:45% 55%;border-radius:22px;overflow:hidden;background:#fff;box-shadow:0 28px 90px rgba(0,0,0,.32);font-family:inherit}\n.ez-auth-brand{background:linear-gradient(145deg,#091c40 0%,#123c70 54%,#07162f 100%);color:#fff;padding:35px;display:flex;flex-direction:column;justify-content:space-between;position:relative;isolation:isolate;overflow:hidden}\n.ez-auth-brand:before{content:"";position:absolute;width:370px;height:370px;border:80px solid rgba(255,255,255,.045);border-radius:50%;right:-220px;top:105px;z-index:-1}\n.ez-auth-brand:after{content:"";position:absolute;width:190px;height:190px;background:#c92332;transform:rotate(25deg);border-radius:36px;bottom:-140px;left:-85px;z-index:-1}\n.ez-auth-brand-top{display:flex;align-items:center;justify-content:space-between;gap:12px}\n.ez-auth-brand-top img{width:112px;max-height:58px;object-fit:contain;background:white;border-radius:7px;padding:5px}\n.ez-auth-brand-top span{font-size:9px;font-weight:800;letter-spacing:1.6px;opacity:.7;text-align:right}\n.ez-auth-brand-line{height:4px;width:46px;background:#ee3044;border-radius:10px;margin-bottom:24px}\n.ez-auth-kicker{font-size:11px;font-weight:800;letter-spacing:2.8px;color:#ffadb7}\n.ez-auth-brand-content h2{font-size:clamp(30px,3vw,43px);line-height:1.13;letter-spacing:-1.4px;color:white;margin:15px 0 17px;font-weight:800}\n.ez-auth-brand-content p{font-size:14px;line-height:1.8;color:#d8e4f5;max-width:320px}\n.ez-auth-perks{display:grid;gap:13px;margin-top:30px}.ez-auth-perks span{display:flex;align-items:center;gap:11px;color:#f2f6ff;font-size:13px;font-weight:600}.ez-auth-perks svg{color:#ff6677}\n.ez-auth-brand-bottom{font-size:10px;letter-spacing:1.2px;font-weight:700;color:#c4d4e9}.ez-auth-brand-bottom span,.ez-auth-mobile-brand span{color:#ff4057;padding:0 6px}\n.ez-auth-main{position:relative;display:flex;align-items:center;justify-content:center;padding:65px 48px 50px;min-width:0}\n.ez-auth-close{position:absolute;right:22px;top:19px;width:36px;height:36px;display:grid;place-items:center;border:1px solid #e4e9f0;border-radius:50%;background:#fff;color:#334155;cursor:pointer}\n.ez-auth-form-wrap{width:100%;max-width:365px}.ez-auth-eyebrow{font-size:11px;font-weight:800;letter-spacing:2px;color:#c92332}\n.ez-auth-form-wrap h2{font-size:34px;line-height:1.2;letter-spacing:-1px;color:#12284b;margin:11px 0}.ez-auth-intro{font-size:14px;color:#64748b;line-height:1.65;margin:0 0 24px}\n.ez-auth-switch{display:flex;background:#f0f3f8;border-radius:11px;padding:5px;gap:4px;margin-bottom:23px}.ez-auth-switch button{flex:1;border:0;border-radius:8px;background:transparent;color:#65758a;font-size:13px;font-weight:700;padding:11px 6px;cursor:pointer}.ez-auth-switch button.active{background:#fff;color:#102c57;box-shadow:0 2px 8px #102c5715}\n.ez-auth-form{display:grid;gap:17px}.ez-auth-form label{display:grid;gap:8px;font-size:13px;font-weight:750;color:#253b58}.ez-auth-form input{box-sizing:border-box;width:100%;height:49px;border:1px solid #d7e0eb;background:#f9fbfd;color:#172b4d;border-radius:9px;padding:0 14px;font-size:15px;outline:none;transition:border-color .2s,box-shadow .2s}.ez-auth-form input:focus{border-color:#215da5;box-shadow:0 0 0 3px #215da51c}.ez-auth-password{position:relative}.ez-auth-password input{padding-right:83px}.ez-auth-password button{position:absolute;right:8px;top:7px;height:35px;padding:0 10px;background:transparent;border:0;color:#215da5;font-weight:750;font-size:12px;cursor:pointer}\n.ez-auth-hint{margin:-5px 0 0;font-size:12px;color:#64748b;line-height:1.5}.ez-auth-error,.ez-auth-success{margin:0;padding:10px 12px;border-radius:8px;font-size:13px;line-height:1.5}.ez-auth-error{background:#fff0f0;color:#a11b28}.ez-auth-success{background:#eaf8f1;color:#136b49}\n.ez-auth-submit{display:flex;align-items:center;justify-content:center;gap:12px;background:#c92332;color:#fff;border:0;border-radius:10px;height:50px;width:100%;font-weight:800;font-size:15px;cursor:pointer;box-shadow:0 6px 18px #c9233233}.ez-auth-submit:disabled{opacity:.65;cursor:wait}.ez-auth-submit:not(:disabled):hover{background:#aa1b2a}\n.ez-auth-bottom{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-top:22px;font-size:12px;color:#64748b}.ez-auth-bottom button{border:0;background:transparent;padding:0;color:#1c5597;font-weight:800;cursor:pointer;font-size:12px}.ez-auth-footnote{display:flex;align-items:center;gap:8px;color:#8a98aa;font-size:11px;margin-top:38px;line-height:1.5}.ez-auth-mobile-brand{display:none}\n@media(max-width:700px){.ez-auth-overlay{padding:12px;align-items:center}.ez-auth-shell{display:block;min-height:0;max-width:460px;border-radius:18px;max-height:calc(100dvh - 24px);overflow-y:auto}.ez-auth-brand{display:none}.ez-auth-main{padding:55px 24px 30px;min-height:0}.ez-auth-mobile-brand{display:block;position:absolute;left:24px;top:23px;color:#12284b;font-size:11px;font-weight:900;letter-spacing:1.3px}.ez-auth-close{right:17px;top:13px}.ez-auth-form-wrap h2{font-size:30px}.ez-auth-footnote{margin-top:26px}}\n@media(max-width:360px){.ez-auth-main{padding-left:17px;padding-right:17px}.ez-auth-bottom{gap:14px}}\n\n/* Secure customer support ticket interface */\n.ez-ticket-page,.ez-ticket-new,.ez-ticket-list,.ez-ticket-detail,.ez-contact-ticket{min-width:0}\n.ez-ticket-page{display:grid;gap:22px}.ez-ticket-new,.ez-ticket-list,.ez-ticket-detail,.ez-contact-ticket{background:#fff;border:1px solid #e4eaf2;border-radius:17px;box-shadow:0 8px 28px #11254b0a;padding:22px}\n.ez-ticket-new h2,.ez-ticket-list h2,.ez-ticket-detail h2{color:#132b51;margin:0 0 12px}.ez-ticket-new form,.ez-ticket-reply{display:grid;gap:14px}.ez-ticket-new label,.ez-ticket-reply label{display:grid;gap:8px;font-weight:700;font-size:13px;color:#253b58}.ez-ticket-new input,.ez-ticket-new textarea,.ez-ticket-reply textarea,.ez-ticket-filters select,.ez-ticket-detail-head select{width:100%;box-sizing:border-box;padding:12px;border:1px solid #d5dfea;border-radius:9px;background:#fbfcff;color:#162b4d;font:inherit}.ez-ticket-new .primary,.ez-ticket-reply .primary{justify-self:start;display:inline-flex;gap:9px;align-items:center}\n.ez-ticket-layout{display:grid;grid-template-columns:minmax(230px, .85fr) minmax(0,1.5fr);gap:18px;align-items:start}.ez-ticket-list-top{display:flex;justify-content:space-between;align-items:center;gap:8px}.ez-ticket-list-top h2{display:flex;align-items:center;gap:8px;font-size:20px}.ez-ticket-list-top button{border:0;background:#f0f4fa;border-radius:7px;padding:8px 11px;cursor:pointer}.ez-ticket-filters{display:flex;gap:8px;align-items:center;justify-content:space-between;margin:12px 0;font-size:12px;color:#64748b}.ez-ticket-filters select{width:auto;max-width:70%}.ez-ticket-item{display:grid;width:100%;text-align:left;gap:8px;margin-top:10px;padding:13px;border:1px solid #e2e8f0;border-radius:10px;background:#fff;color:#24364e;cursor:pointer}.ez-ticket-item.active{border-color:#2856a1;background:#f2f6ff}.ez-ticket-item-title{font-weight:800;overflow-wrap:anywhere}.ez-ticket-item small{color:#64748b}.ez-ticket-status{display:inline-flex;justify-self:start;width:max-content;border-radius:20px;padding:4px 9px;font-size:11px;font-weight:800;background:#fff1d6;color:#905700}.ez-ticket-status.in_progress{background:#e4efff;color:#1b54a3}.ez-ticket-status.resolved{background:#e3f7ed;color:#166534}.ez-ticket-detail-head{display:flex;justify-content:space-between;align-items:start;gap:15px;padding-bottom:18px;border-bottom:1px solid #e7edf4}.ez-ticket-detail-head h2{font-size:21px;overflow-wrap:anywhere}.ez-ticket-detail-head small{color:#64748b}.ez-ticket-detail-head label{display:grid;gap:7px;font-size:12px;font-weight:700;min-width:130px}.ez-ticket-conversation{display:grid;gap:12px;padding:18px 0;max-height:440px;overflow-y:auto}.ez-ticket-bubble{background:#f1f5fa;border-radius:12px;padding:13px;white-space:pre-wrap;overflow-wrap:anywhere}.ez-ticket-bubble.mine{background:#e9f0ff}.ez-ticket-bubble small{color:#66758b}.ez-ticket-bubble p{margin:8px 0 0;line-height:1.6}.ez-ticket-placeholder{min-height:180px;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#718096;text-align:center}.ez-ticket-error{padding:12px;border-radius:9px;background:#fff0f0;color:#a11b28}.ez-ticket-notice{padding:12px;border-radius:9px;background:#eaf8f1;color:#136b49}.ez-contact-ticket{display:flex;flex-direction:column;align-items:flex-start;gap:12px}.ez-contact-ticket h2{margin:0}.ez-contact-ticket p{line-height:1.7;color:#64748b}\n@media(max-width:700px){.ez-ticket-layout{grid-template-columns:1fr}.ez-ticket-new,.ez-ticket-list,.ez-ticket-detail,.ez-contact-ticket{padding:16px}.ez-ticket-detail-head{flex-wrap:wrap}}\n\n/* Premium account dropdown */\n.ez-account-anchor{position:relative;display:flex;align-items:center}\n.ez-account-backdrop{position:fixed;inset:0;z-index:998;background:transparent;border:0;cursor:default}\n.ez-account-menu{position:absolute;top:calc(100% + 15px);right:-46px;width:310px;max-width:calc(100vw - 24px);z-index:999;box-sizing:border-box;background:#fff;border:1px solid #e5eaf2;border-radius:17px;padding:12px;box-shadow:0 18px 50px rgba(14,32,69,.2);color:#172b4d;text-align:left;animation:ez-menu-enter .18s ease-out}\n@keyframes ez-menu-enter{from{opacity:0;transform:translateY(-6px)}to{opacity:1;transform:translateY(0)}}\n.ez-account-menu-header{background:#142b72;border-radius:12px;padding:17px 14px;display:flex;align-items:center;gap:11px;color:white}\n.ez-account-avatar{width:42px;height:42px;flex:none;border:1px solid #8295d0;background:#ffffff16;border-radius:50%;display:grid;place-items:center;color:white}\n.ez-account-menu-header>div:last-child{min-width:0;display:grid;gap:4px}\n.ez-account-menu-header strong{color:white;font-size:15px;line-height:1.25;font-weight:800}\n.ez-account-menu-header span{color:#dce5ff;font-size:11px;line-height:1.4;overflow-wrap:anywhere}\n.ez-account-menu-links{display:grid;gap:2px;padding:10px 2px}\n.ez-account-menu-links button{width:100%;display:flex;align-items:center;gap:12px;padding:12px 10px;background:transparent;border:0;border-radius:9px;color:#24364e;text-align:left;font:inherit;font-size:13px;font-weight:650;cursor:pointer}\n.ez-account-menu-links button>svg:first-child{color:#64748b;flex:none}\n.ez-account-menu-links button span{flex:1}\n.ez-account-menu-links button>svg:last-child{color:#a0aab8;flex:none}\n.ez-account-menu-links button:hover,.ez-account-menu-links button:focus-visible{background:#f0f4fb;outline:none}\n.ez-account-menu-footer{padding:3px 2px 2px}\n.ez-account-menu-footer .ez-account-primary{width:100%;display:flex;align-items:center;justify-content:center;gap:9px;min-height:44px;background:#cf2e2e;color:#fff;border:0;border-radius:10px;font:inherit;font-size:14px;font-weight:800;cursor:pointer}\n.ez-account-menu-footer .ez-account-primary:hover{background:#b92525}\n@media(max-width:700px){.ez-account-menu{position:fixed;top:105px;right:12px;width:min(310px,calc(100vw - 24px));max-height:calc(100dvh - 120px);overflow-y:auto}}\n'}</style>
 <div className="announcement">{t('Shop Online. Rent In Store.')} <span>•</span> {t('Visit our store for rental agreements.')}</div>
 <header><div className="head wrap">
  <button className="hamb" onClick={()=>setMobile(!mobile)}><Menu/></button>
  <button className="logo" onClick={()=>go('Home')}><img src="/logo.jpg" alt="E-Z Rent To Own"/></button>
  <form className="search" onSubmit={e=>{e.preventDefault();runSearch()}}><Search size={20}/><input value={search} onChange={e=>{setSearch(e.target.value);setPage('Search Results')}} placeholder={t('Search products...')} aria-label={t('Search products...')}/><button type="submit" aria-label={t('Search')} style={{background:'transparent',border:0,cursor:'pointer',padding:4}}><ArrowRight size={18}/></button></form>
  <button className="lang" onClick={()=>setLang(lang==='en'?'es':'en')}><Globe size={18}/> {lang==='en'?'Español':'English'}</button>
  <div className="ez-account-anchor">
   <button className="iconbtn" disabled={authLoading} onClick={()=>setAccountMenu(v=>!v)} title={t('My Account')} aria-label={t('My Account')} aria-expanded={accountMenu} aria-haspopup="menu"><User/></button>
   {accountMenu&&<><button className="ez-account-backdrop" aria-label="Close account menu" onClick={()=>setAccountMenu(false)}/><div className="ez-account-menu" role="menu">
    <div className="ez-account-menu-header"><div className="ez-account-avatar"><CircleUserRound size={26}/></div><div><strong>{user?t('My Account'):(lang==='es'?'Bienvenido a E-Z':'Welcome to E-Z')}</strong><span>{user?user.email:(lang==='es'?'Tu cuenta, todo en un lugar':'Your account, all in one place')}</span></div></div>
    <div className="ez-account-menu-links">
     {user?<>
      <button role="menuitem" onClick={()=>go('My Account')}><User size={19}/><span>{t('My Account')}</span><ChevronRight size={17}/></button>
      <button role="menuitem" onClick={()=>go('My Orders')}><Package size={19}/><span>{t('My Orders')}</span><ChevronRight size={17}/></button>
      <button role="menuitem" onClick={()=>go('Payment History')}><CreditCard size={19}/><span>{t('Payment History')}</span><ChevronRight size={17}/></button>
      <button role="menuitem" onClick={()=>go('My Support Tickets')}><Ticket size={19}/><span>{t('My Support Tickets')}</span><ChevronRight size={17}/></button>
      {admin&&<button role="menuitem" onClick={()=>go('Admin Dashboard')}><LayoutDashboard size={19}/><span>{t('Admin Dashboard')}</span><ChevronRight size={17}/></button>}
     </>:<>
      <button role="menuitem" onClick={()=>showAuth('signup')}><UserPlus size={19}/><span>{t('Create Account')}</span><ChevronRight size={17}/></button>
      <button role="menuitem" onClick={()=>showAuth('signin')}><Package size={19}/><span>{t('My Orders')}</span><ChevronRight size={17}/></button>
      <button role="menuitem" onClick={()=>showAuth('signin')}><CreditCard size={19}/><span>{t('Payment History')}</span><ChevronRight size={17}/></button>
     </>}
    </div>
    <div className="ez-account-menu-footer">{user?<button className="ez-account-primary" onClick={signOut}><LogOut size={18}/>{t('Sign Out')}</button>:<button className="ez-account-primary" onClick={()=>showAuth('signin')}><LogIn size={18}/>{t('Sign In')}</button>}</div>
   </div></>}
  </div>
  <button className="cartbtn" onClick={()=>setCartOpen(true)}><ShoppingCart/><b>{cart.length}</b></button>
 </div><nav className={mobile?'open':''}><div className="wrap navinner">{cats.map(c=><button className={page===c?'active':''} onClick={()=>go(c)} key={c}><span className="ez-nav-category-icon"><CategoryIcon category={c} size={20}/></span><span>{t(c)}</span></button>)}</div></nav></header>
 <main>{page==='Home'?<>
  <section className="hero"><div className="wrap hero-inner"><div className="hero-copy"><span className="eyebrow">E-Z RENT TO OWN</span><h1>{t('Make your house')}<br/><em>{t('feel like home.')}</em></h1><p>{t('Furniture, appliances & electronics for every room. Shop outright online or visit us in store to explore rent-to-own options.')}</p><button className="primary" onClick={()=>go('Bedrooms')}>{t('Shop Now')} <ArrowRight size={18}/></button><button className="secondary" onClick={()=>go('Deals')}>{t('Explore Deals')}</button></div><div className="hero-art"><div className="art-circle"/><div className="art-room"><div className="art-cushion"/><div className="art-cushion"/><div className="art-seat"/><div className="art-base"/><div className="art-leg l"/><div className="art-leg r"/></div><div className="art-tag">{t('YOUR HOME.')}<br/><strong>{t('YOUR WAY.')}</strong></div></div></div></section>
  <section className="benefits wrap"><div><Package/><span><b>{t('Shop Your Favorites')}</b><small>{t('Discover products for every room')}</small></span></div><div><ShieldCheck/><span><b>{t('Buy Online')}</b><small>{t('Outright purchases only')}</small></span></div><div><MapPin/><span><b>{t('Rent In Store')}</b><small>{t('Ask about delivery availability')}</small></span></div></section>
  <section className="wrap section"><div className="sectionhead"><div><span className="eyebrow">{t('FIND WHAT YOU LOVE')}</span><h2>{t('Browse Categories')}</h2></div></div><div className="category-grid">{cats.map((c,i)=><button className={'category cat'+i} onClick={()=>go(c)} key={c}><span className="cat-icon ez-home-category-icon"><CategoryIcon category={c} size={48}/></span><strong>{t(c)}</strong><span className="cat-link">{t('Explore collection →')}</span></button>)}</div></section>
  <section className="wrap section"><div className="sectionhead"><div><span className="eyebrow">{t('HANDPICKED FOR YOU')}</span><h2>{t('Featured Products')}</h2></div>{canEditProducts&&<button className="adminadd" onClick={openModal}><Plus size={17}/>{t('Add Product')}</button>}</div>{grid(false)}</section>
 </>:<section className="wrap section page"><div className="breadcrumb"><button onClick={()=>go('Home')}>{t('Home')}</button> / {t(page)}</div><div className="sectionhead"><div><span className="eyebrow">E-Z RENT TO OWN</span><h1>{t(page)}</h1><p className="muted">{isAccount?'Online purchases only':t(isInfo?'Learn more about our store and how we can help.':'Explore our selection. Purchase outright online or visit us to discuss rental options.')}</p></div>{(isInfo?['owner','manager'].includes(staffRole):canEditProducts)&&!isAccount&&page!=='Contact Us'&&page!=='Search Results'&&<button className="adminadd" onClick={openModal}><Plus size={17}/>{t(isInfo?'Add Information':'Add Product')}</button>}</div>
  {isAccount?(!user?<div className="empty"><p>{t('You must be signed in to see this page.')}</p><button className="primary" onClick={()=>showAuth('signin')}>{t('Sign In')}</button></div>:page==='My Account'?<div className="infoarea"><article className="infocard"><h2>{t('Account Details')}</h2><p><strong>{t('Email')}:</strong> {user.email}</p><p>{t('My Orders')} &amp; {t('Payment History')} — online purchases only.</p><button className="primary" onClick={()=>go('My Orders')}>{t('My Orders')}</button> <button className="secondary" onClick={()=>go('Payment History')}>{t('Payment History')}</button> <button className="secondary" onClick={()=>go('My Support Tickets')}><Ticket size={16}/>{t('My Support Tickets')}</button></article></div>:page==='Admin Dashboard'?admin?<AdminCenter role={staffRole} user={user} ticketPanel={ticketPanel} ticketError={ticketError} ticketNotice={ticketNotice}/>:<div className="empty">Access denied.</div>:page==='My Support Tickets'?<div className="ez-ticket-page">{!admin&&<div className="ez-ticket-new"><h2>{t('New Support Ticket')}</h2><p className="muted">Our team will respond here in your account.</p><form onSubmit={createTicket}><label>{t('Subject')}<input name="subject" minLength={3} maxLength={200} required placeholder={t('Subject')}/></label><label>{t('Describe your issue')}<textarea name="description" rows="4" maxLength={10000} required placeholder={t('How can we help?')}/></label><button className="primary" type="submit" disabled={ticketBusy}><Ticket size={17}/>{t('Submit Ticket')}</button></form></div>}{ticketError&&<p className="ez-ticket-error" role="alert">{ticketError}</p>}{ticketNotice&&<p className="ez-ticket-notice" role="status">{ticketNotice}</p>}{ticketPanel}</div>:accountLoading?<div className="empty">Loading...</div>:accountError?<div className="empty">{accountError}</div>:page==='My Orders'?(orders.length?<div className="infoarea">{orders.map(o=><article className="infocard" key={o.id}><h2>{t('Order Number')}: {o.order_number}</h2><p>{t('Date')}: {new Date(o.created_at).toLocaleDateString()}</p><p>{t('Status')}: {o.status}</p><p>{t('Total')}: {money(o.total_amount)}</p></article>)}</div>:<div className="empty">{t('No online orders yet.')}</div>):(payments.length?<div className="infoarea">{payments.map(p=><article className="infocard" key={p.id}><h2>{t('Amount')}: {money(p.amount)}</h2><p>{t('Status')}: {p.status}</p><p>{t('Date')}: {new Date(p.paid_at||p.created_at).toLocaleDateString()}</p></article>)}</div>:<div className="empty">{t('No online payments yet.')}</div>)):
   page==='Search Results'?grid(true):page==='Contact Us'?<div className="contactgrid"><div className="contactcard"><h2>{t("We'd love to hear from you.")}</h2><p>{t('Questions about products, delivery, or renting? Send us a message and our team will get back to you.')}</p><p><MapPin size={18}/> {t('Delivery Area')}</p><small><strong>Berea:</strong> {t('Berea city only (excluding Richmond), Rockcastle County and Jackson County.')} <strong>Irvine:</strong> {t('Estill County, Kentucky. Rental delivery eligibility must be confirmed by the store. Outright online purchases are shipped separately; shipping charges apply.')}</small></div><div className="ez-contact-ticket"><Ticket size={37}/><h2>{user?t('Support Tickets'):t('Please sign in to contact support.')}</h2><p>{user?'Create a support request and follow replies from your account.':'Only registered, signed-in customers can create or view support tickets.'}</p><button className="primary" onClick={()=>user?go('My Support Tickets'):showAuth('signin')}>{user?t('My Support Tickets'):t('Sign In')} <ArrowRight size={17}/></button></div></div>:
   isInfo?<div className="infoarea">{(content[page]||[]).map(item=><article className="infocard" key={item.id}><h2>{lang==='es'?(item.titleEs||item.title):item.title}</h2><p>{lang==='es'?(item.descriptionEs||item.description):item.description}</p>{admin&&<button className="delete" onClick={()=>setContent(v=>({...v,[page]:v[page].filter(i=>i.id!==item.id)}))}><Trash2 size={15}/> {t('Remove')}</button>}</article>)}{!(content[page]||[]).length&&<div className="empty">{t(page==='About E-Z'?'Welcome to E-Z Rent To Own. Browse our products online and visit our store to learn about rental options.':'Interested in joining our team? Contact us to learn about opportunities.')}</div>}</div>:grid(false)}
 </section>}</main>
 <footer><div className="wrap footgrid"><div><img src="/logo.jpg" alt="E-Z Rent To Own"/><p>{t('Making home feel a little more like you.')}</p><small>{t('Outright online purchases are shipped with shipping charges calculated at checkout once payment and shipping services are connected. Rentals are arranged in store only. Berea serves Berea city (not Richmond), Rockcastle and Jackson counties; Irvine serves Estill County. Confirm eligibility with the store.')}</small></div><div><h4>{t('Shop')}</h4>{cats.map(c=><button onClick={()=>go(c)} key={c}>{t(c)}</button>)}</div><div><h4>{t('Company')}</h4>{info.map(c=><button onClick={()=>go(c)} key={c}>{t(c)}</button>)}</div><div><h4>{t('Need Help?')}</h4><p>{t('Have a question about a product or delivery?')}</p><button className="footercontact" onClick={()=>go('Contact Us')}>{t('Contact Our Team →')}</button></div></div><div className="wrap copyright">© {new Date().getFullYear()} E-Z Rent To Own. {t('All rights reserved.')}</div></footer>
 {login&&<div className="ez-auth-overlay" onClick={()=>setLogin(false)} role="presentation">
  <div className="ez-auth-shell" role="dialog" aria-modal="true" aria-label={t(authMode==='signup'?'Create Account':authMode==='reset'?'Forgot Password?':authMode==='newpassword'?'Set New Password':'Sign In')} onClick={e=>e.stopPropagation()}>
   <div className="ez-auth-brand">
    <div className="ez-auth-brand-top"><img src="/logo.jpg" alt="E-Z Rent To Own"/><span>YOUR HOME. YOUR WAY.</span></div>
    <div className="ez-auth-brand-content"><div className="ez-auth-brand-line"/><span className="ez-auth-kicker">E-Z RENT TO OWN</span><h2>{lang==='es'?'Tu hogar comienza aquí.':'A better home starts here.'}</h2><p>{lang==='es'?'Compra tus favoritos en línea y mantén tus pedidos organizados en un solo lugar.':'Shop what you love online and keep every order in one convenient place.'}</p><div className="ez-auth-perks"><span><ShieldCheck size={17}/> {lang==='es'?'Cuenta protegida':'Protected account'}</span><span><Package size={17}/> {t('My Orders')}</span><span><CreditCard size={17}/> {t('Payment History')}</span></div></div>
    <div className="ez-auth-brand-bottom">E-Z RENT TO OWN <span>✦</span> SHOP ONLINE. RENT IN STORE.</div>
   </div>
   <div className="ez-auth-main">
    <button type="button" className="ez-auth-close" onClick={()=>setLogin(false)} aria-label="Close"><X size={21}/></button>
    <div className="ez-auth-mobile-brand">E-Z RENT TO OWN <span>✦</span></div>
    <div className="ez-auth-form-wrap">
     <span className="ez-auth-eyebrow">{authMode==='signup'?(lang==='es'?'ÚNETE A E-Z':'JOIN E-Z RENT TO OWN'):authMode==='reset'?'ACCOUNT RECOVERY':authMode==='newpassword'?'SECURE YOUR ACCOUNT':'WELCOME TO E-Z'}</span>
     <h2>{t(authMode==='signup'?'Create Account':authMode==='reset'?'Forgot Password?':authMode==='newpassword'?'Set New Password':'Sign In')}</h2>
     <p className="ez-auth-intro">{authMode==='signup'?(lang==='es'?'Crea tu cuenta para consultar tus compras en línea.':'Create an account to track your online purchases.'):authMode==='reset'?(lang==='es'?'Te enviaremos un enlace para recuperar tu cuenta.':'We’ll email you a secure link to reset your password.'):authMode==='newpassword'?(lang==='es'?'Elige una contraseña nueva y segura.':'Choose a new secure password for your account.'):(lang==='es'?'Accede a tus pedidos, pagos y datos de cuenta.':'Access your orders, payment history, and account details.')}</p>
     {authMode==='signin'&&<div className="ez-auth-switch"><button type="button" className="active">{t('Sign In')}</button><button type="button" onClick={()=>showAuth('signup')}>{t('Create Account')}</button></div>}
     {authMode==='signup'&&<div className="ez-auth-switch"><button type="button" onClick={()=>showAuth('signin')}>{t('Sign In')}</button><button type="button" className="active">{t('Create Account')}</button></div>}
     <form className="ez-auth-form" onSubmit={submitAuth}>
      {authMode!=='newpassword'&&<label>{t('Email')}<input name="email" type="email" autoComplete="username" placeholder="you@example.com" required/></label>}
      {authMode!=='reset'&&<label>{t('Password')}<div className="ez-auth-password"><input name="password" type={showPassword?'text':'password'} autoComplete={authMode==='signup'||authMode==='newpassword'?'new-password':'current-password'} minLength={6} placeholder="••••••••" required/><button type="button" onClick={()=>setShowPassword(v=>!v)} aria-label={showPassword?'Hide password':'Show password'}>{showPassword?(lang==='es'?'Ocultar':'Hide'):(lang==='es'?'Mostrar':'Show')}</button></div></label>}
      {authMode==='signup'&&<p className="ez-auth-hint">{lang==='es'?'Te enviaremos un enlace para verificar tu correo electrónico.':'We’ll send a verification link to your email address.'}</p>}
      {loginError&&<p className="ez-auth-error" role="alert">{loginError}</p>}
      {loginSuccess&&<p className="ez-auth-success" role="status">{loginSuccess}</p>}
      <button className="ez-auth-submit" disabled={loginBusy} type="submit">{loginBusy?'Please wait...':t(authMode==='signup'?'Create Account':authMode==='reset'?'Send Reset Email':authMode==='newpassword'?'Update Password':'Sign In')} <ArrowRight size={19}/></button>
     </form>
     <div className="ez-auth-bottom">{authMode==='signin'?<><span>{lang==='es'?'¿Nuevo aquí?':'New here?'} <button type="button" onClick={()=>showAuth('signup')}>{t('Create Account')}</button></span><button type="button" onClick={()=>showAuth('reset')}>{t('Forgot Password?')}</button></>:<button type="button" onClick={()=>showAuth('signin')}>← {t('Back to Sign In')}</button>}</div>
     <div className="ez-auth-footnote"><ShieldCheck size={15}/> {lang==='es'?'Tu cuenta está protegida con autenticación segura.':'Your account is protected with secure authentication.'}</div>
    </div>
   </div>
  </div>
 </div>}
 {modal&&canEditProducts&&<div className="overlay" onClick={()=>{if(!saving)setModal(false)}}><div className="dialog" onClick={e=>e.stopPropagation()}><button className="close" disabled={saving} onClick={()=>setModal(false)}><X/></button><h2>{t(isInfo?'Add Information':'Add Product')}</h2><form onSubmit={isInfo?addInfo:addProduct}><label>{t('English title *')}<input name="title" required/></label><label>{t('Spanish title *')}<input name="titleEs" required/></label>{!isInfo&&<><label>{t('Product Image *')}<input type="file" name="image" accept="image/*" required/></label><label>{t('Outright Purchase Price ($) *')}<input name="price" type="number" min="0" step="0.01" required/></label><label>{t('Weekly Rental Price ($) — optional, in-store only')}<input name="weekly" type="number" min="0" step="0.01"/></label>{!cats.includes(page)&&<label>{t('Category')}<select name="category">{cats.map(c=><option key={c}>{c}</option>)}</select></label>}</>}<label>{t('English description')}<textarea name="description" rows="4"/></label><label>{t('Spanish description')}<textarea name="descriptionEs" rows="4"/></label>{formError&&<p role="alert" style={{color:'#b42318'}}>{formError}</p>}<button className="primary" disabled={saving} type="submit">{saving?t('Saving...'):t('Save')}</button></form></div></div>}
 {cartOpen&&<div className="overlay drawerback" onClick={()=>setCartOpen(false)}><aside className="drawer" onClick={e=>e.stopPropagation()}><div className="drawerhead"><h2>{t('Cart')} ({cart.length})</h2><button onClick={()=>setCartOpen(false)}><X/></button></div>{cart.length?cart.map((p,i)=><div className="cartitem" key={i}><img src={p.image} alt=""/><div><b>{lang==='es'?(p.titleEs||p.title):p.title}</b><p>{money(p.price)}</p></div><button onClick={()=>setCart(v=>v.filter((_,j)=>j!==i))}><Trash2 size={17}/></button></div>):<p>{t('Your cart is empty.')}</p>}<div className="carttotal"><strong>{t('Total')}</strong><strong>{money(cart.reduce((a,p)=>a+Number(p.price),0))}</strong></div><p className="muted">{t('Outright purchases only. Secure payment checkout must be connected before accepting orders.')}</p><button className="primary" disabled style={{opacity:.55}}>{t('Checkout — setup required')}</button></aside></div>}
 </>;
}
function ProductGrid({items,t,lang,admin,remove,add,emptySearch=false}){return items.length?<div className="products">{items.map(p=><article className="product" key={p.id}><img src={p.image} alt={lang==='es'?(p.titleEs||p.title):p.title}/><div className="productbody"><small>{t(p.category)}</small><h3>{lang==='es'?(p.titleEs||p.title):p.title}</h3><p>{lang==='es'?(p.descriptionEs||p.description):p.description}</p><div className="price">{money(p.price)} <span>{t('outright')}</span></div>{p.weekly!=null&&<div className="weekly">{money(p.weekly)}/{lang==='es'?'semana':'week'} · {t('Rent In Store')}</div>}<button className="buy" onClick={()=>add(p)}><ShoppingCart size={16}/> {t('Add to Cart')}</button>{admin&&<button className="delete" onClick={()=>remove(p.id)}><Trash2 size={14}/> {t('Delete product')}</button>}</div></article>)}</div>:<div className="emptyproducts"><div className="emptyicon"><Package size={32}/></div><h3>{t(emptySearch?'No products found':'Products coming soon')}</h3><p>{t(emptySearch?'Try another search or browse our categories.':"We're getting our selection ready. Check back soon or visit us in store.")}</p></div>}
createRoot(document.getElementById('root')).render(<App/>);
